mapper.select:
SELECT
    RSNCOD AS VALUE_COL,
    SHORTX AS TEXT_COL
FROM RSNCD 
WHERE DOCUTY = #{DOCUTY} 
  AND OWNRKY = #{SES_OWNER}

SELECT DOCUTY AS VALUE_COL , SHORTX AS TEXT_COL , DOCUTY AS GROUP_COL FROM DOCTM WHERE 1 =1
AND DOCCAT = #{DOCCAT}
AND DOCUTY = #{DOCUTY}
ORDER BY DOCUTY

SELECT COMPKY AS OWNER
FROM WAHMA 
WHERE WAREKY = #{WAREKY}


SELECT	*
FROM	SKUMA
WHERE	1 = 1
AND OWNRKY = #{OWNRKY}
AND SKUKEY = #{SKUKEY}

SELECT DISTINCT MS.PLNTKY AS VALUE_COL , SZF_GET_CMCDV_CDESC1_TEXT(#{LANGKY}, 'LOTA02', MS.PLNTKY) AS TEXT_COL FROM STLMA MS WHERE MS.OWNRKY = #{OWNRKY}
AND MS.WAREKY IN (${WAREKYS})
#{item}
ORDER BY MS.PLNTKY

